import { act, render } from "@testing-library/react";
import React from "react";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

import type * as EChartsModule from "@/lib/echarts";

const state = vi.hoisted(() => ({ options: [] as Array<{ option: { animation?: boolean; series?: unknown[] } }> }));

vi.mock("@/lib/echarts", async () => {
  const actual = await vi.importActual<typeof EChartsModule>("@/lib/echarts");
  return {
    ...actual,
    EChartsContainer: (props: { option: { animation?: boolean; series?: unknown[] } }) => {
      state.options.push(props);
      return React.createElement("div", { "data-testid": "chart" });
    },
  };
});

import { BarChart } from "./BarChart";

describe("BarChart intersection animation", () => {
  let triggerIntersection: ((entry: Partial<IntersectionObserverEntry>) => void) | undefined;
  let observerMock: ReturnType<typeof vi.fn>;

  beforeEach(() => {
    state.options.length = 0;
    observerMock = vi.fn().mockImplementation((callback: IntersectionObserverCallback) => {
      triggerIntersection = (entry) =>
        callback(
          [{ isIntersecting: Boolean(entry.isIntersecting) } as IntersectionObserverEntry],
          {} as IntersectionObserver
        );
      return { observe: vi.fn(), disconnect: vi.fn() };
    });
    vi.stubGlobal("IntersectionObserver", observerMock);
  });

  afterEach(() => {
    vi.unstubAllGlobals();
    triggerIntersection = undefined;
  });

  it("starts collapsed and reveals the values after entering the viewport", () => {
    render(<BarChart data={[{ label: "A", value: 10 }]} animate />);

    expect(observerMock).toHaveBeenCalledOnce();
    expect((state.options[0].option.series?.[0] as { data: Array<{ value: number }> }).data[0].value).toBe(0);

    act(() => {
      triggerIntersection?.({ isIntersecting: true });
    });

    const lastOption = state.options.at(-1)?.option;
    expect((lastOption?.series?.[0] as { data: Array<{ value: number }> }).data[0].value).toBe(10);
    expect(lastOption?.animation).toBe(true);
  });
});

import { describe, expect, it } from "vitest";

import type { ChartTheme } from "@/lib/echarts";

import { buildBarOption } from "./BarChart";

const theme: ChartTheme = {
  textColor: "black",
  mutedTextColor: "gray",
  faintTextColor: "silver",
  axisColor: "rule",
  surfaceColor: "white",
  primaryColor: "gold",
  palette: ["gold", "blue"],
  tokenColors: { "--ks-primary": "gold", "--ks-success": "green" },
};

function getSeriesData(option: ReturnType<typeof buildBarOption>) {
  const series = (option.series as Array<{ data?: Array<Record<string, unknown>> }> | undefined)?.[0];
  return series?.data ?? [];
}

describe("buildBarOption", () => {
  it("uses the primary token for bars without an explicit color", () => {
    const option = buildBarOption(
      [
        { label: "A", value: 8, color: "var(--ks-primary)" },
        { label: "B", value: 4 },
      ],
      { orientation: "vertical", barWidth: 36, showValues: true, showBaseline: true, color: undefined, theme }
    );

    expect(getSeriesData(option)).toEqual([
      expect.objectContaining({ value: 8, itemStyle: { color: "gold" } }),
      expect.objectContaining({ value: 4, itemStyle: { color: "gold" } }),
    ]);
    expect(option.series).toEqual([
      expect.objectContaining({ itemStyle: { borderRadius: 4 }, label: expect.objectContaining({ show: true }) }),
    ]);
  });

  it("renders only one horizontal baseline and supports explicit colors", () => {
    const option = buildBarOption(
      [
        { label: "A", value: 3 },
        { label: "B", value: 7, color: "var(--ks-success)" },
      ],
      { orientation: "horizontal", barWidth: 20, showValues: false, showBaseline: true, color: "purple", theme }
    );

    expect(option.xAxis).toEqual(
      expect.objectContaining({
        type: "value",
        max: 7,
        axisLine: expect.objectContaining({ show: true }),
      })
    );
    expect(option.yAxis).toEqual(
      expect.objectContaining({
        type: "category",
        data: ["A", "B"],
        axisLine: expect.objectContaining({ show: false }),
      })
    );
    expect(getSeriesData(option)).toEqual([
      expect.objectContaining({ value: 3, itemStyle: { color: "purple" } }),
      expect.objectContaining({ value: 7, itemStyle: { color: "green" } }),
    ]);
  });

  it("only shows vertical values when the rendered bar is taller than 12 pixels", () => {
    const option = buildBarOption(
      [
        { label: "Short", value: 1 },
        { label: "Tall", value: 10 },
      ],
      { orientation: "vertical", barWidth: 20, showValues: true, showBaseline: true, height: 100, visible: true, theme }
    );

    expect(getSeriesData(option)).toEqual([
      expect.objectContaining({ label: { show: false } }),
      expect.objectContaining({ label: { show: true } }),
    ]);
  });

  it("keeps animated bars collapsed until the chart becomes visible", () => {
    const option = buildBarOption([{ label: "A", value: 10 }], {
      orientation: "vertical",
      barWidth: 20,
      showValues: true,
      showBaseline: true,
      animate: true,
      visible: false,
      theme,
    });

    expect(option.animation).toBe(false);
    expect(getSeriesData(option)).toEqual([expect.objectContaining({ value: 0, label: { show: false } })]);
  });
});

import type React from "react";

export interface BarChartItem {
  label: string;
  value: number;
  color?: string;
}

export interface BarChartProps {
  data: BarChartItem[];
  height?: number;
  /** Largura total do SVG — só usado em orientation="horizontal" (reserva espaço pro label + trilha da barra). */
  width?: number;
  barWidth?: number;
  gap?: number;
  showValues?: boolean;
  showBaseline?: boolean;
  color?: string;
  animate?: boolean;
  /** @default "vertical" */
  orientation?: "vertical" | "horizontal";
  className?: string;
  style?: React.CSSProperties;
}

"use client";

import type { EChartsOption } from "echarts";
import { useEffect, useState } from "react";

import { EChartsContainer } from "@/lib/echarts";
import { resolveChartColor, resolveChartTheme } from "@/lib/echarts/chart-theme";
import { cn } from "@/lib/utils";

import type { BarChartItem, BarChartProps } from "./bar-chart.types";

interface BarOptionArgs {
  orientation: "vertical" | "horizontal";
  barWidth: number;
  showValues: boolean;
  showBaseline: boolean;
  color?: string;
  theme: ReturnType<typeof resolveChartTheme>;
  height?: number;
  animate?: boolean;
  visible?: boolean;
}

export function buildBarOption(data: BarChartItem[], args: BarOptionArgs): EChartsOption {
  const {
    orientation,
    barWidth,
    showValues,
    showBaseline,
    color,
    theme,
    height = 200,
    animate = false,
    visible = true,
  } = args;
  const max = Math.max(...data.map((item) => item.value), 1);
  const values = data.map((item) => {
    const fill = item.color
      ? resolveChartColor(item.color, theme.tokenColors)
      : color
        ? resolveChartColor(color, theme.tokenColors)
        : theme.primaryColor;
    const rendered = visible ? item.value : 0;
    return {
      value: rendered,
      itemStyle: { color: fill },
      label: {
        show: showValues && visible && (orientation === "horizontal" || (item.value / max) * (height - 32) > 12),
      },
    };
  });
  const axis = {
    axisLine: { show: showBaseline, lineStyle: { color: theme.axisColor } },
    axisTick: { show: false },
    axisLabel: { color: theme.faintTextColor },
  };
  return {
    animation: animate && visible,
    grid: { left: orientation === "horizontal" ? 72 : 8, right: 12, top: 12, bottom: 28, containLabel: true },
    xAxis:
      orientation === "horizontal"
        ? { type: "value", max, ...axis }
        : { type: "category", data: data.map((item) => item.label), ...axis },
    yAxis:
      orientation === "horizontal"
        ? {
            type: "category",
            data: data.map((item) => item.label),
            axisLine: { show: false },
            axisTick: { show: false },
            axisLabel: { color: theme.faintTextColor },
            data: data.map((item) => item.label),
          }
        : { type: "value", max, ...axis },
    series: [
      {
        type: "bar",
        barWidth,
        data: values,
        itemStyle: { borderRadius: 4 },
        label: { show: showValues, formatter: ({ value }: { value: unknown }) => String(value) },
      },
    ],
  };
}

export function BarChart({
  data,
  height = 200,
  width = 320,
  barWidth = 36,
  gap: _gap = 12,
  showValues = true,
  showBaseline = true,
  color,
  animate = true,
  orientation = "vertical",
  className,
  style,
}: BarChartProps) {
  const [visible, setVisible] = useState(!animate);
  useEffect(() => {
    if (!animate || typeof IntersectionObserver === "undefined") {
      setVisible(true);
      return;
    }
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setVisible(true);
          observer.disconnect();
        }
      },
      { threshold: 0.1 }
    );
    const element = document.querySelector(
      `[aria-label="Bar chart: ${data.map((item) => `${item.label} ${item.value}`).join(", ")}"]`
    );
    if (element) observer.observe(element);
    return () => observer.disconnect();
  }, [animate, data]);
  const theme = resolveChartTheme();
  const summary = data.map((item) => `${item.label} ${item.value}`).join(", ");
  return (
    <EChartsContainer
      className={cn(className)}
      style={style}
      option={buildBarOption(data, {
        orientation,
        barWidth,
        showValues,
        showBaseline,
        color,
        theme,
        height,
        animate,
        visible,
      })}
      width={orientation === "horizontal" ? width : "100%"}
      height={orientation === "horizontal" ? Math.max(data.length * (barWidth + 12) - 12, barWidth) : height}
      ariaLabel={`Bar chart: ${summary}`}
    />
  );
}
